"""Bind aggregate source-recovery outputs and explicit unresolved evidence gates."""
from __future__ import annotations
from release_paths import path as _release_path, resolve_config as _release_resolve_config, source_path as _release_source_path, font_path as _release_font_path
import json
import subprocess
import sys
from pathlib import Path
from recover_nested_source import HERE, OLD, ROOT, identity, load

def write(name, obj):
    with (HERE / name).open('x', encoding='utf-8', newline='\n') as f:
        json.dump(obj, f, ensure_ascii=True, indent=2)
        f.write('\n')

def main():
    nested = load(HERE / 'nested_literal_recovery.json')
    sch = load(HERE / 'sch_fresh_units_and_timing_gate.json')
    geo = load(HERE / 'residence_source_provenance.json')
    comparison = load(HERE / 'native_city_original_value_comparison.json')
    strict = load(HERE / 'strict_ambiguity_sensitivity.json')
    assert all((x['passed'] for x in (nested, sch, geo, comparison, strict)))
    assert nested['raw_source_hash_sequence'] == geo['raw_source_hash_sequence'] == comparison['source_hash_sequence'] == strict['source_hash_sequence']
    assert nested['counts']['raw_unique_contents'] == geo['counts']['unique_contents'] == comparison['counts']['contents'] == 2329
    assert nested['counts']['matched_record_occurrences'] == geo['counts']['record_occurrences'] == comparison['counts']['source_link_token_replays'] == 5744
    assert strict['source_record_token_replays'] == 5744 and strict['source_contents_replayed'] == 2329
    assert all((c['strict_processed_rows'] <= c['broad_processed_rows'] for c in strict['coverage']))
    assert nested['counts'].get('python_literal_decoded_occurrences', 0) == 0
    assert sch['raw_source_files_freshly_hashed'] == 34
    assert sch['all_sources_unchanged_since_prior_all_sheet_audit']
    assert not any((x['unit_fields'] or x['onset_fields'] or x['first_result_availability_fields'] for x in sch['fresh_text_schema_checks']))
    assert len(sch['fresh_processed_assay_column_checks']) == 8
    tests = subprocess.run([sys.executable, '-m', 'unittest', 'test_source_recovery.py'], cwd=HERE, capture_output=True, text=True, check=True)
    whu_prior = OLD / 'whu/whu_interval_candidate_layers_v1.json'
    whu = load(whu_prior)
    assert whu['layered_stay_counts']['source_interval_candidate_stays'] == 19
    assert whu['layered_stay_counts']['layer_3_no_observed_prior_or_index_mace_flags_stays'] == 0
    gates = [{'id': 'T1', 'requirement': 'Same-admission linkage', 'status': 'partial', 'evidence': 'WHU 5,744 frozen source-record occurrences independently replay patient and both stay-day tokens; SCH prior 179,832 agreed stays remain bound to identical raw source bytes.', 'remaining': 'Date-key linkage is not a certified encounter export contract or exhaustive diagnosis capture.'}, {'id': 'T2', 'requirement': '0-hour absence at admission and first-event definition', 'status': 'partial', 'evidence': 'SCH has 16 source POA-absent acute-component candidates in 31,384 first-recorded index stays; WHU 19 source interval candidates leave zero after observed prior/index flags.', 'remaining': 'The SCH candidates are not adjudicated first MACE and lack complete negatives, nonfatal status, cardiovascular death and validated heart-failure hospitalization components.'}, {'id': 'T3', 'requirement': '24/48-hour event-free landmark risk sets', 'status': 'not_established', 'evidence': 'All 16 selected SCH admission-to-discharge component intervals cross both later cutoffs. No structured onset or recoverable nested literal clock was found.', 'remaining': 'Event-specific onset or an independently adjudicated interval entirely after each landmark.'}, {'id': 'T4', 'requirement': 'Predictor first clinical availability', 'status': 'not_established', 'evidence': 'SCH processed measurements have date-only timing; WHU report timestamps are not verified first clinical visibility. The separate examination review clock cannot be assigned to laboratories.', 'remaining': 'LIS result release/first visible timestamps with documented semantics and unique source measurement/encounter binding.'}, {'id': 'T5', 'requirement': 'Complete same-stay diagnoses and clinical negative capture', 'status': 'not_established', 'evidence': 'No completeness/count contract recovered; SCH seventh slot occupied in 112,375/179,832 stays remains a truncation warning, not proof of truncation.', 'remaining': 'Full encounter diagnosis manifest/counts including revisions and a validated encounter-level negative capture definition.'}, {'id': 'T6', 'requirement': 'Cause-specific death and heart-failure hospitalization', 'status': 'not_established', 'evidence': 'Existing death cause fields and same-stay I50 candidates remain unadjudicated; clock conflict and hospitalization-cause semantics remain.', 'remaining': 'Cause-of-death hierarchy/adjudication, death-clock reconciliation, and a source-supported principal HF admission definition.'}, {'id': 'U1', 'requirement': 'SCH measurement identity, units and scale', 'status': 'not_established', 'evidence': '34 source files freshly hashed; seven text schemas reread; eight albumin/total-protein/Hb/Hct columns contain processed numeric values but no unit dictionary. Independent NJM lab branch uses identical SCH input and also disallows numeric transfer.', 'remaining': 'Original item/specimen/unit dictionary and raw values or reversible transformation parameters linking each model input to the originating assay.'}, {'id': 'U2', 'requirement': 'Three-centre six-direction common numeric assay transfer', 'status': 'gate_not_met', 'evidence': 'No new source-supported SCH unit evidence. Existing two-direction WHU/MIMIC restricted assay analysis remains distinct.', 'remaining': 'Pass U1 before four SCH directions are fit; preserve each centre label/unit/time window and do not present diagnostic label transport as unified incident-risk validation.'}, {'id': 'G1', 'requirement': 'WHU native city provenance and original regional value assignment', 'status': 'partial_new_evidence', 'evidence': 'Exact source residence/hukou city names now compared against the original workbook after internal patient/stay-token replay, separately for every original data sheet and candidate lab/admission year.', 'remaining': 'Subset-only coverage and an unverified historical year/assignment rule; no causal, healthcare-access or fairness interpretation is validated by a numeric match.'}]
    requests = [{'source': 'SCH original LIS item dictionary and measurements', 'required_fields': ['study input column', 'source item ID/name', 'specimen', 'unit', 'raw numeric value', 'processed-scale transformation and parameters', 'patient linkage key', 'encounter linkage key', 'specimen collection time', 'result-release/first-visible time'], 'acceptance': 'Trace each selected common assay to its original value/unit and measurement; no unit inferred from range or borrowed from another centre.'}, {'source': 'SCH and WHU encounter diagnosis export contract', 'required_fields': ['encounter key', 'all diagnosis rows', 'slot identity', 'principal/secondary role', 'complete count/manifest', 'local POA code-label dictionary', 'revision/deletion status', 'diagnosis documentation time', 'event-specific onset time or adjudicated interval'], 'acceptance': 'Explain coverage, exclusions and slot truncation; explicitly separate onset from documentation and permit independent negative capture verification.'}, {'source': 'SCH and WHU death/HF adjudication', 'required_fields': ['encounter key', 'death date/time', 'underlying and contributing causes', 'cause classification and adjudication', 'HF principal admission reason', 'prior HF hospitalization history'], 'acceptance': 'Do not equate all-cause death with cardiovascular death or any I50 code with hospitalization caused by HF.'}, {'source': 'WHU original regional assignment ledger/code', 'required_fields': ['patient/encounter key', 'residence versus hukou rule', 'assigned city', 'economic year and lag rule', 'original workbook/sheet/version', 'missing-value and transformation policy'], 'acceptance': 'Exact linkage independent of model values; candidate-year agreement alone is not a recovered assignment algorithm.'}]
    write('evidence_gates.json', {'execution_complete': True, 'gates': gates, 'minimum_source_requests': requests, 'new_incident_labels': 0, 'new_models': 0, 'all_scientific_gaps_closed': False, 'prior_conditional_component_evidence': identity(whu_prior)})
    artifacts = [p for p in sorted(HERE.iterdir()) if p.is_file() and p.suffix in {'.py', '.json', '.md'} and (p.name != 'completion.json')]
    write('completion.json', {'passed': True, 'execution_complete': True, 'matched_WHUsource_hash_sequences_equal_across_four_fresh_traversals': True, 'unit_tests_passed': True, 'unit_tests_output': tests.stdout + tests.stderr, 'outputs': [identity(p) for p in artifacts], 'source_files_modified': False, 'manuscripts_modified': False, 'patient_level_records_exported': False, 'scientific_gates_all_passed': False})
    print(json.dumps({'passed': True, 'gates': len(gates), 'tests': 8, 'all_scientific_gaps_closed': False}))
if __name__ == '__main__':
    main()
